def _bm_key(row_data):
    """採点結果を一意に識別するキー（日付+曲名+スコア）"""
    return f"{row_data.get('日付','')}|{row_data.get('曲名','')}|{row_data.get('総合得点','')}"

def toggle_bookmark_row(row_data):
    key = _bm_key(row_data)
    if key in _bookmarks:
        _bookmarks.discard(key)
    else:
        _bookmarks.add(key)
    _save_json(BOOKMARK_FILE, list(_bookmarks))

def is_bookmarked(row_data):
    return _bm_key(row_data) in _bookmarks

