        return {"tags": data, "color": TAG_DEFAULT_COLOR}
    if isinstance(data, str):         # さらに古い形式互換
        return {"tags": [data] if data else [], "color": TAG_DEFAULT_COLOR}
    return {
        "tags":  data.get("tags", []),
        "color": data.get("color", TAG_DEFAULT_COLOR),
    }

def set_user_tags_list(song_title, tags_list, color=TAG_DEFAULT_COLOR):
    """tags_list: 最大5つのタグ文字列リスト"""
    tags_list = [t.strip() for t in tags_list if t.strip()][:5]
    if tags_list:
        _user_tags[song_title] = {"tags": tags_list, "color": color}
    else:
        _user_tags.pop(song_title, None)
    _save_json(USER_TAG_FILE, _user_tags)

def get_tags_str(song_title):
    """一覧表示用：タグを ' / ' で連結"""
    return " / ".join(get_user_tags_full(song_title)["tags"])

